import csv
rows=list(csv.reader(open("/root/PlaywrightTest1/data/current_202609.csv",encoding="cp932",errors="replace")))
want=[("7","加藤　龍一"),("7","木村　駿"),("8","久須見　高広"),("8","唐鎌　美穂"),("8","園田　貞子"),("9","三浦　未久美"),("9","並木　啓悦"),("9","吉川　洋"),("9","唐鎌　美穂"),("9","安永　愛菜"),("9","山岡　由美子"),("9","清水　洋之"),("9","菅原　華純"),("9","麻生　真理奈"),("9","井川　裕太"),("10","久須見　高広"),("10","井川　裕太"),("10","前川　七海"),("10","前川　心愛"),("10","加藤　龍一"),("10","松戸　きよ"),("10","林　修"),("10","森田　美穂子"),("10","石川　えみ"),("11","一ノ瀬　祐里枝"),("11","並木　啓悦"),("11","井川　裕太"),("11","唐鎌　美穂"),("11","安永　愛菜"),("12","久須見　高広")]
def norm(s): return s.replace("\u3000","").replace(" ","")
for d,u in want:
    hits=[r for r in rows[1:] if r[9]==d and norm(r[11])==norm(u)]
    print(f"9/{d:<2} {u:<8} : " + (" | ".join(f"{r[14]}-{r[15]} {norm(r[0])}{('+'+norm(r[2])) if r[2] else ''} {r[13][-6:]}" for r in hits) if hits else "(カイポケに行なし)"))
